import {uniquePairs} from './memory-engine.js';
const TAU=Math.PI*2,clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const wrapAngle=a=>Math.atan2(Math.sin(a),Math.cos(a));
const raw=t=>({x:165*Math.sin(t)+30*Math.sin(2*t),y:3*Math.sin(2*t)+4,z:130*Math.cos(t)+20*Math.sin(3*t)});
export const TRACK=[];let length=0;
for(let i=0;i<=720;i++){const p=raw(i/720*TAU);if(i)length+=Math.hypot(p.x-TRACK[i-1].x,p.y-TRACK[i-1].y,p.z-TRACK[i-1].z);TRACK.push({...p,s:length});}
export const TRACK_LENGTH=length,ROAD_HALF=7,TOTAL_DISTANCE=length*3;
export function trackAt(distance){let s=((distance%length)+length)%length,lo=0,hi=720;while(lo+1<hi){const mid=(lo+hi)>>1;if(TRACK[mid].s<=s)lo=mid;else hi=mid;}const a=TRACK[lo],b=TRACK[lo+1],f=(s-a.s)/(b.s-a.s),t=(lo+f)/720*TAU,eps=.003,p=raw(t),prev=raw(t-eps),next=raw(t+eps),tx=next.x-prev.x,tz=next.z-prev.z,n=Math.hypot(tx,tz);const h=Math.atan2(tx,tz),p2=raw(t-2*eps),n2=raw(t+2*eps),h0=Math.atan2(p.x-p2.x,p.z-p2.z),h1=Math.atan2(n2.x-p.x,n2.z-p.z);return {...p,tx:tx/n,tz:tz/n,nx:-tz/n,nz:tx/n,heading:h,curve:wrapAngle(h1-h0)/Math.hypot(next.x-prev.x,next.z-prev.z)};}
export const ITEMS={turbo:{icon:'🚀',name:'ロケット',help:'約3秒ダッシュ'},shield:{icon:'🫧',name:'バブル',help:'6秒ガード＋短い加速'},pulse:{icon:'⚡',name:'パルス',help:'前方70mの1台を減速'},comet:{icon:'🌟',name:'コメット',help:'4秒ダッシュ＋ガード'}};
const shuffle=(list,r)=>{const a=[...list];for(let i=a.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
export class KartGame{
 constructor(entries,{random=Math.random}={}){this.pack=uniquePairs(entries);if(this.pack.length<4)throw Error('異なる訳の単語を4組以上用意してください。');this.random=random;this.phase='ready';this.paused=false;this.time=0;this.countdown=3;this.distance=0;this.lateral=0;this.speed=0;this.steer=0;this.steering=0;this.drifting=false;this.drift=0;this.boost=0;this.shield=0;this.slow=0;this.coins=0;this.item=null;this.correct=0;this.answered=0;this.gate=0;this.misses=new Map();this.reviewQueue=[];this.deck=[];this.recent=[];this.events=[];this.rewardId=0;this.starTotal=0;this.lastLap=1;this.attackAt=18;this.incoming=0;this.collisionCooldown=0;this.driftCount=0;this.itemsUsed=0;this.finishedRank=0;this.playerFinishTime=null;this.ai=Array.from({length:5},(_,i)=>({id:i+1,distance:4+i*3,lateral:(i%3-1)*3,speed:31.5+i*.6,slow:0,boost:0,nextBoost:12+i*2,finishTime:null}));this.pickups=[];for(let lap=0;lap<3;lap++)for(let i=0;i<15;i++)this.pickups.push({id:lap*15+i,distance:lap*length+length*(.07+i*.061),lateral:[-3.5,0,3.5][i%3],kind:i%5===4?'oil':i%3===0?'pad':'coin',taken:false});this.gates=Array.from({length:9},(_,i)=>length*(Math.floor(i/3)+[.2,.51,.82][i%3]));}
 emit(type,data={}){this.events.push({type,...data});}
 reward(label,points){this.starTotal+=points;this.emit('reward',{key:'kart-'+(++this.rewardId),label,points});}
 get rank(){return 1+this.ai.filter(a=>a.finishTime!==null||a.distance>this.distance).length;}
 get lap(){return Math.min(3,Math.floor(this.distance/length)+1);}
 get nextGate(){return this.gates[this.gate]??Infinity;}
 start(){if(this.phase!=='ready')return false;this.phase='countdown';return true;}
 input(steer,drift=false){this.steer=clamp(Number(steer)||0,-1,1);if(this.phase!=='race'||this.paused){this.steer=0;this.drifting=false;this.drift=0;return;}if(this.drifting&&!drift&&this.drift>=.7){const level=this.drift>=1.8?2:1;this.boost=Math.max(this.boost,level===2?1.8:1);this.driftCount++;this.emit('drift',{level});}this.drifting=!!drift;if(!drift)this.drift=0;}
 clearInput(){this.steer=0;this.steering=0;this.drifting=false;this.drift=0;}
 pause(value){this.paused=value;this.clearInput();}
 ask(review=false){this.clearInput();this.isReview=review;let pair;if(review){pair=this.reviewWords[this.reviewIndex];}else{const due=this.reviewQueue.findIndex(p=>p.due<=this.answered);if(due>=0)pair=this.reviewQueue.splice(due,1)[0].pair;else{const allowed=p=>!this.recent.includes(p.word)&&!this.reviewQueue.some(q=>q.pair.word===p.word);let idx=this.deck.findIndex(allowed);if(idx<0){this.deck=shuffle(this.pack.filter(allowed),this.random);idx=0;}pair=this.deck.splice(idx,1)[0];}}this.pair=pair;if(!review){this.recent.push(pair.word);this.recent=this.recent.slice(-2);}this.reverse=review||this.gate%2===1;this.options=shuffle([pair,...shuffle(this.pack.filter(p=>p!==pair&&p.word!==pair.word),this.random).slice(0,3)],this.random);this.phase='quiz';this.emit('question');}
 answer(index){if(this.phase!=='quiz'||this.paused||!this.options[index])return false;const right=this.options[index].word===this.pair.word;this.lastCorrect=right;if(!this.isReview){this.answered++;this.gate++;if(right){this.correct++;this.boost=Math.max(this.boost,2.5);this.reward('単語クリア',10);if(!this.item){const pool=this.rank>=4?['turbo','comet','pulse']:['turbo','shield','pulse'];this.item=pool[Math.floor(this.random()*pool.length)];}else this.shield=Math.max(this.shield,2);this.emit('correct');}else{this.misses.set(this.pair.word,this.pair);this.reviewQueue=this.reviewQueue.filter(p=>p.pair.word!==this.pair.word);this.reviewQueue.push({pair:this.pair,due:this.answered+2});this.emit('wrong');}}this.phase='feedback';return right;}
 continue(){if(this.phase!=='feedback'||this.paused)return false;if(this.isReview){if(this.lastCorrect)this.reviewIndex++;if(this.reviewIndex>=this.reviewWords.length){this.phase='reviewDone';this.emit('reviewDone');}else this.ask(true);}else{this.phase='race';this.clearInput();}return true;}
 startReview(){if(this.phase!=='done'||this.paused||!this.misses.size)return false;this.reviewWords=[...this.misses.values()];this.reviewIndex=0;this.ask(true);return true;}
 useItem(){if(this.phase!=='race'||this.paused||!this.item)return false;const kind=this.item;if(kind==='pulse'){const target=this.ai.filter(a=>a.finishTime===null&&a.distance>this.distance&&a.distance-this.distance<=70).sort((a,b)=>a.distance-b.distance)[0];if(!target){this.emit('noTarget');return false;}target.slow=2.2;this.emit('hitRival',{id:target.id});}if(kind==='turbo')this.boost=Math.max(this.boost,3);if(kind==='shield'){this.shield=6;this.boost=Math.max(this.boost,1);}if(kind==='comet'){this.shield=5;this.boost=Math.max(this.boost,4);}this.item=null;this.itemsUsed++;this.emit('item',{kind});return true;}
 hit(){if(this.shield>0){this.emit('blocked');return;}this.slow=1.5;this.coins=Math.max(0,this.coins-2);this.emit('hit');}
 finish(){this.distance=TOTAL_DISTANCE;this.playerFinishTime=this.time;this.finishedRank=this.rank;this.phase='done';this.clearInput();this.reward('完走',20+(6-this.finishedRank)*10);if(this.correct===9)this.reward('全問正解',50);this.emit('finish');}
 tick(dt){if(this.paused||!Number.isFinite(dt)||dt<=0)return;let remaining=Math.min(dt,.25);if(this.phase==='countdown'){this.countdown-=remaining;if(this.countdown<=0){this.phase='race';this.emit('go');}return;}while(remaining>0&&this.phase==='race'){const step=Math.min(remaining,1/120);remaining-=step;this.step(step);}}
 step(dt){this.time+=dt;for(const key of ['boost','shield','slow','collisionCooldown'])this[key]=Math.max(0,this[key]-dt);const track=trackAt(this.distance),offroad=Math.abs(this.lateral)>ROAD_HALF-.45;const target=(32+this.coins*.32)*(this.boost>0?1.48:1)*(this.slow>0?.5:1)*(offroad?.55:1);this.speed+=(target-this.speed)*Math.min(1,dt*3);this.steering+=(this.steer-this.steering)*(1-Math.exp(-dt*12));const outward=clamp(track.curve*this.speed*this.speed*.12,-3.2,3.2);this.lateral=clamp(this.lateral+(this.steering*(this.drifting?7.6:6.5)+outward)*dt,-9,9);
 if(this.drifting&&Math.abs(this.steer)>.1&&Math.abs(track.curve)>.002&&Math.sign(this.steer)===-Math.sign(track.curve)&&!offroad&&this.speed>18)this.drift=Math.min(2.6,this.drift+dt);else if(this.drifting)this.drift=Math.max(0,this.drift-dt*.8);
 const old=this.distance;this.distance+=this.speed*dt;
 for(const a of this.ai){if(a.finishTime!==null)continue;a.slow=Math.max(0,a.slow-dt);a.boost=Math.max(0,a.boost-dt);if(this.time>a.nextBoost){a.boost=1.1;a.nextBoost+=15+a.id;}const aiSpeed=a.speed*(a.slow>0?.5:1)*(a.boost>0?1.25:1);a.distance+=aiSpeed*dt;a.lateral=3.4*Math.sin(a.distance/65+a.id*1.7);if(a.distance>=TOTAL_DISTANCE){a.distance=TOTAL_DISTANCE;a.finishTime=this.time;}if(Math.abs(a.distance-this.distance)<2.1&&Math.abs(a.lateral-this.lateral)<2.6&&this.collisionCooldown===0){this.lateral=clamp(this.lateral+(this.lateral>=a.lateral?.8:-.8),-9,9);this.speed*=.9;this.collisionCooldown=.65;this.emit('bump');}}
 for(const p of this.pickups){if(p.taken||p.distance<old-3||p.distance>this.distance+1)continue;if(Math.abs(p.lateral-this.lateral)<1.7){p.taken=true;if(p.kind==='coin'){this.coins=Math.min(8,this.coins+1);this.emit('coin');}if(p.kind==='pad'){this.boost=Math.max(this.boost,1.4);this.emit('pad');}if(p.kind==='oil')this.hit();}}
 if(this.incoming>0){this.incoming=Math.max(0,this.incoming-dt);if(this.incoming===0)this.hit();}else if(this.time>=this.attackAt){this.attackAt+=20;if(this.ai.some(a=>a.finishTime===null&&Math.abs(a.distance-this.distance)<55)){this.incoming=1.8;this.emit('incoming');}}
 if(this.lap>this.lastLap){this.lastLap=this.lap;this.emit('lap',{lap:this.lap});}
 if(this.distance>=this.nextGate){this.distance=this.nextGate;this.ask();return;}if(this.distance>=TOTAL_DISTANCE)this.finish();
 }
}
